/* 统一列表工具异步模拟接口；导入批次独立于业务实体，不能绕过审批。 */
window.EamListToolsApi=(()=>{
 const copy=x=>JSON.parse(JSON.stringify(x));
 async function rows(page){const config=EAM_LIST_TOOLS_JSON.pages[page];if(!config)throw Error('页面不支持列表工具');if(config.endpoint)return (await EamProblemApi.request('GET','/'+config.endpoint)).rows;const s=Eam.s;const sources={equipmentRecords:s.equipmentRecords,checks:s.checks,tasks:[s.task,...s.taskInstances],plans:[...s.planHistory,s.plan,...(s.planDraft?[s.planDraft]:[])],routes:[{id:'ROUTE-DEMO-001',name:s.plan.route,status:s.plan.status}],standards:[...s.standardHistory,s.standard,...(s.standardDraft?[s.standardDraft]:[])],templates:s.assetMaster?.templates||[],locations:s.assetMaster?.locations||[]};return sources[config.source]||[];}
 async function request(method,path,body={}){await Promise.resolve();if(['failure','conflict'].includes(Eam.s.scenario))throw Error('模拟接口失败或版本冲突，请保留文件后重试');const page=body.page;if(!EAM_LIST_TOOLS_JSON.pages[page])throw Error('不支持的列表类型');
 if(method==='GET'&&path==='/list-tools/export')return {schema:1,page,scope:'当前角色可读取范围，不限当前分页',rows:copy(await rows(page))};
 if(method==='POST'&&path==='/list-tools/import/validate'){if(!Eam.can(['engineer','supervisor']))throw Error('当前角色没有导入权限');const data=body.data;if(data?.schema!==1||data.page!==page||!Array.isArray(data.rows))throw Error('格式应为schema=1、当前page、rows数组');if(!data.rows.length||data.rows.length>500)throw Error('每批须为1–500条');const ids=new Set(),errors=[];const existing=await rows(page);data.rows.forEach((r,i)=>{const key=r?.id||r?.code;if(!r||typeof r!=='object'||Array.isArray(r)||!key)errors.push({row:i+1,message:'缺少id或code'});else if(ids.has(key)||existing.some(x=>(x.id||x.code)===key))errors.push({row:i+1,message:'批次内或当前数据已存在相同标识'});ids.add(key);});return {rows:copy(data.rows),errors,count:data.rows.length};}
 if(method==='POST'&&path==='/list-tools/import'){if(!Eam.can(['engineer','supervisor']))throw Error('当前角色没有导入权限');const prior=JSON.parse(sessionStorage.getItem('eam-import-batches')||'[]').find(x=>body.idempotencyKey&&x.idempotencyKey===body.idempotencyKey&&x.createdBy===Eam.s.person&&x.page===page);if(prior)return {id:prior.id,count:prior.rows.length,status:prior.status};const result=await request('POST','/list-tools/import/validate',body);if(result.errors.length)throw Error('请先修正校验错误');if(!body.reason?.trim())throw Error('请填写导入原因');const batch={id:crypto.randomUUID(),idempotencyKey:body.idempotencyKey,page,status:'pending_mapping_review',rows:result.rows,reason:body.reason,createdBy:Eam.s.person,at:new Date().toISOString()};const all=JSON.parse(sessionStorage.getItem('eam-import-batches')||'[]');all.push(batch);sessionStorage.setItem('eam-import-batches',JSON.stringify(all));return {id:batch.id,count:result.count,status:batch.status};}throw Error('未定义的列表工具接口');}
 return {request};
})();
